    if (!r.value.has_value())
        check(r.value.error() == PpmReadError::kBadNumber, "hash in data -> kBadNumber");
}

void test_too_many_pixels() {
    auto ss = std::istringstream("P3\n1 1\n255\n0 0 0 255 255 255\n");
    auto r = Image::read(ss);
    check(!r.value.has_value(), "extra pixel -> error");
    if (!r.value.has_value())
        check(r.value.error() == PpmReadError::kTooManyPixels, "extra -> kTooManyPixels");
}

void test_too_few_pixels() {
    auto ss = std::istringstream("P3\n2 2\n255\n0 0 0 255 0 0 0 255 0\n");
    auto r = Image::read(ss);
    check(!r.value.has_value(), "missing pixel -> error");
    if (!r.value.has_value())
        check(r.value.error() == PpmReadError::kTooFewPixels, "missing -> kTooFewPixels");
}

void test_error_line() {
    auto ss = std::istringstream("P3\n1 1\n255\nx 0 0\n");
    auto r = Image::read(ss);
    check(!r.value.has_value(), "not a number -> error");
    check(r.line == 4, "bad number reported on line 4");

    ss = std::istringstream("P3\n1 1\n255\n256 0 0\n");
    r = Image::read(ss);
    check(!r.value.has_value(), "channel 256 -> error");
    check(r.line == 4, "channel range reported on line 4");

    ss = std::istringstream("P3\n1 1\n100\n0 0 0\n");
    r = Image::read(ss);
    check(!r.value.has_value(), "maxval=100 -> error");
    check(r.line == 3, "maxval reported on line 3");
}

// Memory resources for the allocation seam tests.
//
// Note: in a debug build std::pmr::vector allocates its container proxy in the
// (noexcept) constructor, so a resource that fails the very first allocation
// would terminate instead of letting the caller handle bad_alloc. Fail on a
// later call instead.
class FailingMemoryResource : public std::pmr::memory_resource {
  public:
    // Only fails allocations under Pixel (alignment 1). Service allocations
    // (e.g. _Container_proxy in Debug MSVC) have higher alignment and are
    // not counted, making the seam deterministic across Debug/Release.
    explicit FailingMemoryResource(int fail_on_call) : fail_on_call_(fail_on_call) {}

  private:
    static_assert(alignof(Pixel) == 1,
                  "Filter relies on Pixel having alignment 1; service allocations "
                  "(e.g. _Container_proxy) have higher alignment.");

    void* do_allocate(std::size_t bytes, std::size_t alignment) override {
        if (alignment == alignof(Pixel) && ++calls_ == fail_on_call_)
            throw std::bad_alloc();
        return std::pmr::new_delete_resource()->allocate(bytes, alignment);
    }
    void do_deallocate(void* p, std::size_t bytes, std::size_t alignment) override {
        std::pmr::new_delete_resource()->deallocate(p, bytes, alignment);
    }
    bool do_is_equal(const std::pmr::memory_resource& other) const noexcept override {
        return this == &other;
    }
    int fail_on_call_;
    int calls_ = 0;
};

class RecordingMemoryResource : public std::pmr::memory_resource {
  public:
    std::size_t max_bytes() const { return max_bytes_; }

  private:
    // Tracks only vector allocations; string/token use std::allocator
    void* do_allocate(std::size_t bytes, std::size_t alignment) override {
        if (bytes > max_bytes_)
            max_bytes_ = bytes;
        return std::pmr::new_delete_resource()->allocate(bytes, alignment);
    }
    void do_deallocate(void* p, std::size_t bytes, std::size_t alignment) override {
        std::pmr::new_delete_resource()->deallocate(p, bytes, alignment);
    }
    bool do_is_equal(const std::pmr::memory_resource& other) const noexcept override {
        return this == &other;
    }
    std::size_t max_bytes_ = 0;
};

void test_huge_header_does_not_allocate() {
    RecordingMemoryResource rec;
    auto ss = std::istringstream("P3\n2147483647 2147483647\n255\n0 0 0\n");
    auto r = Image::read(ss, &rec);
    check(!r.value.has_value(), "huge header -> error");
    if (!r.value.has_value())
        check(r.value.error() == PpmReadError::kTooFewPixels, "huge header -> kTooFewPixels");
    check(rec.max_bytes() <= 16, "huge header -> no header-sized allocation");
    // sizeof(Pixel)=3, multiplier≈5 => 16; one allocation, no growth
}

void test_alloc_failure() {
    FailingMemoryResource fail(2);
    auto ss = std::istringstream("P3\n2 2\n255\n0 0 0 255 0 0 0 255 0 0 0 255\n");
    auto r = Image::read(ss, &fail);
    check(!r.value.has_value(), "alloc failure -> error");
    if (!r.value.has_value())
        check(r.value.error() == PpmReadError::kAllocError, "alloc failure -> kAllocError");
    check_diag(r, "строка 4: не удалось выделить память; размещено пикселей: 1",
               "alloc failure diagnostic");
}

void test_alloc_failure_first() {
    FailingMemoryResource fail(1);
    auto ss = std::istringstream("P3\n2 2\n255\n0 0 0 255 0 0 0 255 0 0 0 255\n");
    auto r = Image::read(ss, &fail);
    check(!r.value.has_value(), "first alloc failure -> error");
    if (!r.value.has_value())
        check(r.value.error() == PpmReadError::kAllocError, "first alloc failure -> kAllocError");
    check_diag(r, "строка 4: не удалось выделить память; размещено пикселей: 0",
               "first alloc failure diagnostic");
    // RecordingMemoryResource outlives Image — vector holds pointer to mr
}

void test_overflow_header() {
    auto ss = std::istringstream("P3\n2147483648 1\n255\n0 0 0\n");
    auto r = Image::read(ss);
    check(!r.value.has_value(), "2147483648 -> error");
    if (!r.value.has_value())
        check(r.value.error() == PpmReadError::kBadNumber, "2147483648 -> kBadNumber");
    check_diag(r, "строка 2: число превышает допустимый диапазон", "overflow header diagnostic");
}

void test_too_few_pixels_partial() {
    auto ss = std::istringstream("P3\n2 2\n255\n0 0 0 255 0 0 0 255 0\n");
    auto r = Image::read(ss);
    check(!r.value.has_value(), "3 pixels -> error");
    if (!r.value.has_value())
        check(r.value.error() == PpmReadError::kTooFewPixels, "3 pixels -> kTooFewPixels");
    check_diag(r, "строка 5: получено только 3 пикселей (ожидалось 4)", "3 pixels diagnostic");
}

// Serves `data`, then fails with `err` (errno) via ios_base::failure, which
// puts the stream into the bad state.
class FailingInputBuf : public std::streambuf {
  public:
    FailingInputBuf(std::string data, int err) : data_(std::move(data)), err_(err) {
        char* p = data_.data();
        setg(p, p, p + data_.size());
    }

  protected:
    // errno may be overwritten by stdlib calls before the diagnostic reads it — works in practice
    int_type underflow() override {
        errno = err_;
        throw std::ios_base::failure("simulated io error");
    }

  private:
    std::string data_;
    int err_;
};

void test_read_io_error() {
    FailingInputBuf sbuf("P3\n1 1\n255\n", EIO);
    std::istream is(&sbuf);
    auto r = Image::read(is);
    check(!r.value.has_value(), "read io error -> error");
    if (!r.value.has_value()) {
        check(r.value.error() == PpmReadError::kIOError, "read io error -> kIOError");
        auto expected = std::string("сбой чтения: ") + std::generic_category().message(EIO) +
                        " (errno " + std::to_string(EIO) + ")";
        check_diag(r, expected, "read io error diagnostic");
    }
}

void test_header_negative() {
    auto ss = std::istringstream("P3\n-5 1\n255\n0 0 0\n");
    auto r = Image::read(ss);
    check(!r.value.has_value(), "width -5 -> error");
    if (!r.value.has_value()) {
        check(r.value.error() == PpmReadError::kBadNumber, "width -5 -> kBadNumber");
        check_diag(r, "строка 2: ширина должна быть положительным числом; получено: -5",
                   "width -5 diagnostic");
    }

    ss = std::istringstream("P3\n1 -5\n255\n0 0 0\n");
