#include "parse_args.h"
#include "patterns.h"

#include <errno.h>

#include "../../common/c/ppm_io.h"
#include "../../common/c/strerror.h"

static int generate_ppm(const struct ParseResult* args) {
    struct PpmWriter writer;
    ppm_writer_init(&writer, stdout, args->size, args->size);
    uint32_t state = args->seed;
    for (int32_t y = 0; y < args->size; ++y)
        for (int32_t x = 0; x < args->size; ++x) {
            struct RGB c = {0};
            switch (args->pattern) {
            case PATTERN_GRADIENT:
                c = gradient_pixel(x, y, args->size);
                break;
            case PATTERN_CHECKER:
                c = checker_pixel(x, y);
                break;
            case PATTERN_RADIAL:
                c = radial_pixel(x, y, args->size);
                break;
            case PATTERN_RANDOM:
                c = random_pixel(&state);
                break;
            }
            ppm_writer_put(&writer, c.r, c.g, c.b);
        }

    if (ppm_writer_finish(&writer) != 0) {
        char errbuf[256];
        safe_strerror(errno, errbuf, sizeof errbuf);
        fprintf(stderr, "сбой записи в поток: %s (errno %d)\n", errbuf, errno);
        return EC_IOERR;
    }
    return EC_OK;
}

int main(int argc, char** argv) {
    struct ParseResult args = parse_args(argc, argv);

    if (args.request == PR_HELP) {
        print_usage();
        return EC_OK;
    }

    if (args.request == PR_VERSION) {
        print_version();
        return EC_OK;
    }

    if (args.error != PE_OK) {
        switch (args.error) {
        case PE_NOARG:
            fprintf(stderr, "N не указано. Использование: gen_image <N> [pattern]\n");
            return EC_USAGE;
        case PE_BADNUMBER:
            fprintf(stderr, "N должно быть целым числом; получено: %s\n", argc >= 2 ? argv[1] : "");
            return EC_USAGE;
        case PE_BADPATTERN:
            fprintf(stderr, "Неизвестный паттерн: %s. Допустимые: gradient, checker, radial\n",
                    argc >= 3 ? argv[2] : "");
            return EC_USAGE;
        case PE_BADSEED:
            fprintf(stderr,
                    "seed должно быть целым числом в диапазоне [0; 4294967295]; "
                    "получено: %s\n",
                    argc >= 5 ? argv[4] : "");
            return EC_USAGE;
        }
    }

    if (args.size < 1) {
        fprintf(stderr, "размер должен быть положительным; получено: %d\n", args.size);
        return EC_USAGE;
    }

    if (args.pattern != PATTERN_RANDOM && args.size > 512) {
        fprintf(stderr, "N должно быть в [1; 512]; получено: %d\n", args.size);
        return EC_USAGE;
    }

    return generate_ppm(&args);
}

