    check(r.error == PE_OK, "crlf input -> PE_OK");
    if (r.error == PE_OK) {
        check(strcmp(r.name, "морской закат") == 0, "crlf: name");
        check(r.count == 1920, "crlf: count");
        free(r.name);
    }
    fclose(f);
}

static void test_read_bad_count_crlf(void) {
    FILE* f = make_input("тест\r\nabc\r\n");
