            if (y > s.y_max)
                s.y_max = y;
        }

        int32_t bin = (int32_t)(y * 8.0 / (s.max_val + 1));
        if (bin >= 8)
            bin = 7;
        ++s.histogram[bin];
        ++s.pixel_count;
    }

    return s;
}

void ppm_print_stats(const Stats& s, std::ostream& os) {
    int32_t avg_r = (int32_t)((double)s.total_r / s.pixel_count + 0.5);
